//! Champion scoring for the draft.
//!
//! score = kit prior × map fit + team-composition needs + learned synergy with
//! allies (eᵢᵀ S eⱼ) + learned counters vs revealed enemy picks (eᵢᵀ C eⱼ).
//! S and C start at zero and are fitted from self-play drafts (P-040, P-002).

use crate::bc_draft::map::MapDescriptor;
use crate::bc_brain::champvec::{bilinear, ChampVec, LEN};
use crate::bc_core::champion::{ChampionKind, DraftChoice};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DraftState {
    pub ally: Vec<DraftChoice>,
    pub enemy: Vec<DraftChoice>,
    pub team_size: usize,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ScorerWeights {
    pub synergy: [[i8; LEN]; LEN],
    pub counter: [[i8; LEN]; LEN],
    /// Score units per bilinear unit.
    pub bilinear_scale: f32,
}

impl Default for ScorerWeights {
    fn default() -> Self {
        Self { synergy: [[0; LEN]; LEN], counter: [[0; LEN]; LEN], bilinear_scale: 1.0 / 2000.0 }
    }
}

impl ScorerWeights {
    /// Untrained weights: the bilinear terms are zero, so skip them (each costs
    /// ~1k fuel, enough to starve later draft turns, which only get 100k).
    #[must_use]
    pub fn is_zero(&self) -> bool {
        self.synergy.iter().chain(&self.counter).all(|row| row.iter().all(|&x| x == 0))
    }
}

/// Hand priors for farming strength (tuned by experiments; see backlog).
fn prior(choice: DraftChoice, m: &MapDescriptor) -> f32 {
    use DraftChoice as D;
    match choice {
        // Splash basic attacks clear multi-camp groups fast; shield tanks aggro.
        D::Varg => 1.0 + 0.6 * m.clustered,
        D::Ryth => 0.9 + 0.3 * m.clustered + 0.3 * m.monolith,
        // Two bodies for one pick doubles farming throughput (linked deaths).
        D::CassiAndIssac => 1.0,
        D::VesperVale => 0.95 + 0.2 * m.size,
        D::Stellar => 0.85 + 0.3 * m.clustered,
        D::Marcella => 0.8 + 0.2 * m.monolith,
        // Kill resets cooldowns: many small camps keep the resets rolling.
        D::Vendetta => 0.75 + 0.2 * m.n_groups.min(1.0),
        D::Tavi => 0.7 + 0.2 * m.size,
        D::Prism => 0.7 + 0.1 * m.clustered,
        D::Ren => 0.65,
        D::Willow => 0.6,
        // Engine 1.0.0 bruiser: tanky, stronger as it takes damage; a stunning dash for camps.
        D::HeartOfRuin => 0.8 + 0.2 * m.clustered,
    }
}

fn is_tank(v: &ChampVec) -> bool {
    v[0] >= 80
}

fn is_ranged(v: &ChampVec) -> bool {
    v[3] >= 64
}

/// Score one candidate given the draft so far.
pub fn score(
    choice: DraftChoice,
    map: &MapDescriptor,
    state: &DraftState,
    vec_of: &dyn Fn(ChampionKind) -> ChampVec,
    weights: &ScorerWeights,
) -> f32 {
    let mut s = prior(choice, map);
    let mine: Vec<ChampVec> = choice.champions().iter().map(|&k| vec_of(k)).collect();
    let allies: Vec<ChampVec> =
        state.ally.iter().flat_map(|c| c.champions().iter().map(|&k| vec_of(k))).collect();
    let enemies: Vec<ChampVec> =
        state.enemy.iter().flat_map(|c| c.champions().iter().map(|&k| vec_of(k))).collect();
    let picks_left = state.team_size.saturating_sub(state.ally.len());

    // Composition: someone must tank camp aggro; ranged damage is safer on camps.
    if picks_left <= 2 && !allies.iter().any(is_tank) && mine.iter().any(is_tank) {
        s += 0.3;
    }
    if !allies.iter().any(is_ranged) && mine.iter().any(is_ranged) {
        s += 0.1;
    }
    // Willow's heal only pays off with frontliners to keep alive.
    if choice == DraftChoice::Willow && allies.iter().filter(|v| is_tank(v)).count() >= 2 {
        s += 0.3;
    }

    if weights.is_zero() {
        return s;
    }
    for m in &mine {
        for a in &allies {
            s += bilinear(m, &weights.synergy, a) as f32 * weights.bilinear_scale;
        }
        for e in &enemies {
            s += bilinear(m, &weights.counter, e) as f32 * weights.bilinear_scale;
        }
    }
    s
}

/// Highest-scoring choice not yet on our team (ties → lowest engine value).
#[must_use]
pub fn best_pick(
    map: &MapDescriptor,
    state: &DraftState,
    vec_of: &dyn Fn(ChampionKind) -> ChampVec,
    weights: &ScorerWeights,
) -> Option<DraftChoice> {
    DraftChoice::ALL
        .iter()
        .copied()
        .filter(|c| !state.ally.contains(c))
        .map(|c| (score(c, map, state, vec_of, weights), c))
        .max_by(|a, b| a.0.total_cmp(&b.0).then_with(|| b.1.cmp(&a.1)))
        .map(|(_, c)| c)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bc_draft::map::tests::sample_map;
    use crate::bc_brain::champvec::from_kit;
    use crate::bc_core::champion::builtin_kit;

    fn vec_of(k: ChampionKind) -> ChampVec {
        from_kit(&builtin_kit(k))
    }

    #[test]
    fn never_picks_twice_and_always_picks_something() {
        let map = MapDescriptor::from_map(&sample_map());
        let mut state = DraftState { ally: vec![], enemy: vec![], team_size: 5 };
        for _ in 0..5 {
            let pick = best_pick(&map, &state, &vec_of, &ScorerWeights::default()).unwrap();
            assert!(!state.ally.contains(&pick));
            state.ally.push(pick);
        }
        assert_eq!(state.ally.len(), 5);
    }

    #[test]
    fn clustered_maps_favour_splash() {
        let mut m = MapDescriptor::from_map(&sample_map());
        m.clustered = 1.0;
        let state = DraftState { ally: vec![], enemy: vec![], team_size: 3 };
        assert_eq!(
            best_pick(&m, &state, &vec_of, &ScorerWeights::default()),
            Some(DraftChoice::Varg)
        );
    }

    #[test]
    fn late_picks_fill_a_missing_tank() {
        let m = MapDescriptor::from_map(&sample_map());
        let state = DraftState {
            ally: vec![DraftChoice::Stellar, DraftChoice::VesperVale],
            enemy: vec![],
            team_size: 3,
        };
        let pick = best_pick(&m, &state, &vec_of, &ScorerWeights::default()).unwrap();
        assert!(pick.champions().iter().any(|&k| is_tank(&vec_of(k))), "{pick:?}");
    }

    #[test]
    fn learned_synergy_changes_the_pick() {
        let m = MapDescriptor::from_map(&sample_map());
        let state = DraftState { ally: vec![DraftChoice::Varg], enemy: vec![], team_size: 3 };
        let mut w = ScorerWeights::default();
        // Strong positive synergy along "spell power" for pairs with Varg.
        w.synergy[2][0] = 127;
        w.bilinear_scale = 1.0 / 20.0;
        let plain = best_pick(&m, &state, &vec_of, &ScorerWeights::default()).unwrap();
        let pick = best_pick(&m, &state, &vec_of, &w).unwrap();
        assert_ne!(pick, plain, "the synergy term changes the pick");
        // ...towards the highest spell power (vector dimension 2).
        let power = |c: DraftChoice| c.champions().iter().map(|&k| vec_of(k)[2]).max().unwrap();
        let best = DraftChoice::ALL.iter().map(|&c| power(c)).max().unwrap();
        assert_eq!(power(pick), best, "{pick:?}");
    }
}
